from pathlib import Path

path = Path('lib/product/p5_information_architecture/p5_verification_workspaces.dart')
text = path.read_text(encoding='utf-8')
old = """          Card(\n            key: const Key('saved-run-evidence-index'),\n            child: Padding(\n              padding: const EdgeInsets.all(16),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: <Widget>[\n                  Text(\n                    'Saved evidence • ${savedRun.title}',\n                    style: Theme.of(context).textTheme.titleLarge,\n                  ),\n                  const SizedBox(height: 8),\n                  Text('${evidence.length} supported viewer types'),\n                  const SizedBox(height: 8),\n                  for (final item in evidence)\n                    ListTile(\n                      key: Key('evidence-item-${item.kind.name}'),\n                      selected: item.id == selected?.id,\n                      leading: Icon(_evidenceKindIcon(item.kind)),\n                      title: Text(item.kind.label),\n                      subtitle: Text(\n                        advanced\n                            ? '${item.summary}\\n${item.mediaType} • ${item.byteLength} bytes'\n                            : item.summary,\n                      ),\n                      trailing: const Icon(Icons.chevron_right),\n                      onTap: () => controller.selectEvidence(item.id),\n                    ),\n                ],\n              ),\n            ),\n          ),\n          if (selected != null) ...<Widget>[\n            const SizedBox(height: 12),\n            _evidenceViewer(context, selected),\n          ],\n"""
new = """          Card(\n            key: const Key('saved-run-evidence-index'),\n            child: Padding(\n              padding: const EdgeInsets.all(16),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: <Widget>[\n                  Text(\n                    'Saved evidence • ${savedRun.title}',\n                    style: Theme.of(context).textTheme.titleLarge,\n                  ),\n                  const SizedBox(height: 8),\n                  Text('${evidence.length} supported viewer types'),\n                  const SizedBox(height: 12),\n                  LayoutBuilder(\n                    builder: (context, constraints) {\n                      final index = SizedBox(\n                        height: 420,\n                        child: SingleChildScrollView(\n                          key: const Key('saved-run-evidence-scroll'),\n                          child: Column(\n                            children: <Widget>[\n                              for (final item in evidence)\n                                ListTile(\n                                  key: Key('evidence-item-${item.kind.name}'),\n                                  selected: item.id == selected?.id,\n                                  leading: Icon(_evidenceKindIcon(item.kind)),\n                                  title: Text(item.kind.label),\n                                  subtitle: Text(\n                                    advanced\n                                        ? '${item.summary}\\n${item.mediaType} • ${item.byteLength} bytes'\n                                        : item.summary,\n                                  ),\n                                  trailing: const Icon(Icons.chevron_right),\n                                  onTap: () => controller.selectEvidence(item.id),\n                                ),\n                            ],\n                          ),\n                        ),\n                      );\n                      final viewer = selected == null\n                          ? const _BoundaryNotice(\n                              message:\n                                  'Choose a supported saved-run evidence type to open its viewer.',\n                            )\n                          : _evidenceViewer(context, selected);\n                      if (constraints.maxWidth >= 900) {\n                        return Row(\n                          crossAxisAlignment: CrossAxisAlignment.start,\n                          children: <Widget>[\n                            SizedBox(width: 360, child: index),\n                            const SizedBox(width: 16),\n                            Expanded(child: viewer),\n                          ],\n                        );\n                      }\n                      return Column(\n                        crossAxisAlignment: CrossAxisAlignment.stretch,\n                        children: <Widget>[\n                          index,\n                          const SizedBox(height: 12),\n                          viewer,\n                        ],\n                      );\n                    },\n                  ),\n                ],\n              ),\n            ),\n          ),\n"""
count = text.count(old)
if count != 1:
    raise SystemExit(f'expected one evidence layout anchor, found {count}')
path.write_text(text.replace(old, new, 1), encoding='utf-8', newline='\n')
